export const IMPORTER_SCRIPT = [
  '// Generated by GameUI Studio. Drop into Assets/Scripts/Editor/.',
  '// It only writes texture import settings and .meta files; run it after copying the',
  '// PNGs into Assets/Art/Textures/UI/<Module>/, then let Unity import and refresh.',
  '#if UNITY_EDITOR',
  'using UnityEditor;',
  'using UnityEngine;',
  '',
  'public static class GameUiSliceImporter',
  '{',
  '    [MenuItem("Tools/GameUI/Apply UI Import Settings")]',
  '    public static void Apply()',
  '    {',
  '        var guids = AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/Art/Textures/UI" });',
  '        int changed = 0;',
  '        foreach (var guid in guids)',
  '        {',
  '            var path = AssetDatabase.GUIDToAssetPath(guid);',
  '            var importer = AssetImporter.GetAtPath(path) as TextureImporter;',
  '            if (importer == null) continue;',
  '',
  '            importer.textureType = TextureImporterType.Sprite;',
  '            importer.spriteImportMode = SpriteImportMode.Single;',
  '            importer.alphaIsTransparency = true;',
  '            importer.mipmapEnabled = false;',
  '            importer.wrapMode = TextureWrapMode.Clamp;',
  '            importer.filterMode = FilterMode.Bilinear;',
  '            importer.spritePixelsPerUnit = 100;',
  '            var textureSettings = new TextureImporterSettings();',
  '            importer.ReadTextureSettings(textureSettings);',
  '            textureSettings.spriteAlignment = (int)SpriteAlignment.Center;',
  '            textureSettings.spritePivot = new Vector2(0.5f, 0.5f);',
  '            importer.SetTextureSettings(textureSettings);',
  '            importer.textureCompression = TextureImporterCompression.Compressed;',
  '',
  '            importer.SaveAndReimport();',
  '            changed++;',
  '        }',
  '',
  '        AssetDatabase.Refresh();',
  '        Debug.Log($"[GameUI] Applied sprite import settings to {changed} textures.");',
  '    }',
  '}',
  '#endif',
  '',
].join('\n');

export const README_NOTE = [
  '# UI 素材导出包',
  '',
  '由 GameUI Studio 生成。',
  '',
  '## 结构',
  '',
  '- `png/` - 透明 PNG 素材，按 UI 规范命名 `T_UI_<模块>_<对象>[_<状态>].png`',
  '- `manifest.json` - 每张图的坐标、类型、状态、九宫格建议',
  '- `coords.json` - 只含原图坐标，供自行还原布局',
  '- `GameUiSliceImporter.cs` - Unity Editor 脚本，批量设置 Sprite 导入参数',
  '',
  '## 导入步骤',
  '',
  '1. 把 `png/` 内文件复制到 `Assets/Art/Textures/UI/<模块>/`',
  '2. 把 `GameUiSliceImporter.cs` 放到 `Assets/Scripts/Editor/`',
  '3. Unity 菜单 `Tools/GameUI/Apply UI Import Settings`',
  '4. 等待 Unity 完成导入与刷新',
  '',
  '## 注意',
  '',
  '- 九宫格建议只是候选值，`manifest.json` 的 `nineSlice.suggested` 为 true 时需人工确认边框像素。',
  '- `kind: text` 的元素建议在引擎内用 TMP 文本节点还原，不要当成图片使用。',
  '- 文本仅在 includeTextAsImage 开启、审核通过且有切片时导出 PNG；关闭开关时 manifest、coords 和 PNG 均排除文本。',
  '- 无可导出图片时停止导出；重名文件自动添加数字后缀，manifest、coords 与 PNG 使用同一文件名。',
  '- extractionMethod 记录提取来源：color-key（色键）、segmentation（分割）、repaint（重绘）、manual（手工）；旧数据未知时省略。',
  '- needsAi 只表示补图意图，不代表成功；repainted 仅来自成功标记或 repaint 提取方式。',
  '- processingStatus / processingError 保留处理状态与错误，失败后导出的原图回退可据此识别。',
  '- imageSize 是 PNG 像素尺寸；sourceMapping 将完整 PNG 的 destination 矩形映射回原图 source 矩形，尺寸不同表示缩放。当前切片无独立裁剪偏移，不推测 trim offset。',
  '- `repainted: true` 的素材由模型补全遮挡后重绘，风格可能与原图略有差异，需人工复核。',
  '',
].join('\n');
